label("100", (0,20), W);
label("400", (100,80), E);
label("100", (20,0), S);
label("500", (100,0), S);
label("500", (0,100), W);
fill((0,0)--(100,100)--(100,80)--(20,0)--cycle, gray(.7));
fill((0,0)--(100,100)--(80,100)--(0,20)--cycle, gray(.7));
[/asy]

